(function (global) {

    function loadScript(src) {
      return new Promise(function (resolve, reject) {
  
        var s = document.createElement("script");
  
        s.src = src;
        s.async = false;
  
        s.onload = function () {
          requestAnimationFrame(resolve);
        };
  
        s.onerror = function () {
          reject(new Error("Failed to load: " + src));
        };
  
        document.head.appendChild(s);
  
      });
    }
  
  
    async function init() {
  
      if (document.readyState !== "complete") {
        await new Promise(resolve =>
          window.addEventListener("load", resolve, { once: true })
        );
      }
  
      if (!global.gsap) {
        console.error("❌ GSAP belum diload");
        return;
      }
  
      try {
  
        console.log("Loading SplitMotion modules...");
  
        await loadScript(
          "https://cdn.jsdelivr.net/gh/yuzuyyy/splitMotion@main/dist/split-motion.min.js"
        );
  
        await loadScript(
          "https://cdn.jsdelivr.net/gh/yuzuyyy/splitMotion@main/dist/scramble.min.js"
        );
  
        await loadScript(
          "https://cdn.jsdelivr.net/gh/yuzuyyy/splitMotion@main/dist/pixelTwo.min.js"
        );
  
        await loadScript(
          "https://cdn.jsdelivr.net/gh/yuzuyyy/splitMotion@main/dist/marquee.min.js"
        );
  
        global.SplitMotionBundleReady = true;
  
        console.log("✅ SplitMotion Bundle Loaded Successfully");
  
        // optional auto init
        if (global.myMotion && global.myMotion.init) {
          global.myMotion.init();
        }
  
      }
      catch (err) {
  
        console.error("❌ Gagal load bundle:", err);
  
      }
  
    }
  
    init();
  
  })(window);
  